('de42e92a-167f-4334-a655-9177f66e132f', 'Jean Prouvé: Maison Démountable', 'exhibition'::event_type, 'one of Prouvé’s models of the 6×6 house from 1944, which will be a permanent installation in the garden of the gallery space', array['Jean Prouvé']::text[], array['installation']::text[], array['outdoor','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2024/05/240509-LadbrokeHallGarden-0047.jpg', '2024-05-16', '2026-12-31', null, null, 'Carpenters', '79 Barlby Road, W10 6AZ, London', 'W10 6AZ', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/jean-prouve-maison-demountable/', '2026-11-14T10:21:30.653Z', 0.85, 'jean prouve maison demountable|carpenters|2024-05-16'),
('9243b6b7-b441-4c39-aba0-9d029c108316', 'Anne Ryan: Folkmoot', 'exhibition'::event_type, 'named after an Old English word for “a gathering of people” Ryan’s new site-specific commission responds directly to the gallery’s archaeological site to bring ancient and contemporary London into dialogue', array['Anne Ryan']::text[], array['installation']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/07/London-Mithraeum-Bloomberg-SPACE-Anne-Ryan-1.webp', '2026-07-16', '2027-01-09', null, null, 'London Mithraeum Bloomberg SPACE', '12 Walbrook, EC4N 8AA, London', 'EC4N 8AA', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/folkmoot/', '2026-11-14T10:21:30.653Z', 0.85, 'anne ryan folkmoot|london mithraeum bloomberg space|2026-07-16'),
