('5984e174-9f38-42ee-aebc-3ceff796fff7', 'Richard Baker: Anticipation of Memory', 'exhibition'::event_type, 'an exhibition bringing together works made over the past decade where Baker began painting particular eBay furniture listings he found when moving house “a way of owning something before, or instead of, having it', array['Richard Baker']::text[], array['painting']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/11/BRINK-Richard-Baker-6.webp', '2026-09-23', '2026-11-14', null, null, 'BRINK', 'The People’s Hall, 2 Olaf Street, W11 4BE, London', 'W11 4BE', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/richard-baker-anticipation-of-memory/', '2026-11-14T10:21:30.653Z', 0.85, 'richard baker anticipation of memory|brink|2026-09-23'),
('f90b7bbe-9994-4688-a00d-e6cb7d73e0f7', 'Emrys Williams: what seas what shores what grey rocks', 'exhibition'::event_type, 'Emrys knows … that he is ‘dragging things forth’, that they remain a mystery to the rest of us, and only just within his own reach, as passing from memory, like dreams on waking, endlessly reconfigured” - John Gillett', array['Emrys Williams']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/Benjamin-Rhodes-Emrys-Williams-1.webp', '2026-09-24', '2026-11-21', null, null, 'Benjamin Rhodes Arts', '62 Old Nichol Street, E2 7HP, London', 'E2 7HP', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/emrys-williams-what-seas-what-shores-what-grey-rocks/', '2026-11-14T10:21:30.653Z', 0.85, 'emrys williams what seas what shores what grey rocks|benjamin rhodes arts|2026-09-24'),
('baa5338d-84c5-4ee7-a43c-57dac7ce0352', 'Jonathan Baldock: For Your Keeping', 'exhibition'::event_type, 'a new body of small-scale works in the form of votive objects, keepsakes, and bodily hybrids made in ceramic and textile', array['Jonathan Baldock']::text[], array['ceramics','textiles']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/OH_1166d-49.jpg', '2026-09-24', '2026-11-20', null, null, 'Canopy Collections', '3 Bloomsbury Place, WC1A 2QA, London', 'WC1A 2QA', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/jonathan-baldock-for-your-keeping/', '2026-11-14T10:21:30.653Z', 0.85, 'jonathan baldock for your keeping|canopy collections|2026-09-24'),
('14c9eecb-9602-445d-a7ad-8668fc41176a', 'Hugo Winder-Lind: 140 Knights in Silver Armour', 'exhibition'::event_type, 'the debut of ambitious sculptural and video work as Winder-Lind draws both on a 19th century English fable and the fabric of the gallery to create an entire world rendered in vivid and whimsical detail', array['Hugo Winder-Lind']::text[], array['sculpture','film']::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Robbie-von-Kampen.webp', '2026-09-25', '2026-11-14', null, null, 'Robbie von Kampen', '31 Old Compton Street, 1st Floor, W1D 5JS, London', 'W1D 5JS', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/hugo-winder-lind-140-knights-in-silver-armour/', '2026-11-14T10:21:30.653Z', 0.85, 'hugo winder lind 140 knights in silver armour|robbie von kampen|2026-09-25'),
('75e8769b-24ba-4ee5-a8ad-26281ceb271a', 'SOFT SERVE', 'exhibition'::event_type, 'in the first exhibition at the collaborative space, five artists who consider belonging, vulnerability, material memory, and the unstable boundaries between bodies, objects and places', '{}'::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Soft-Serve-Flatmates-37.webp', '2026-09-25', '2026-11-14', null, null, 'Flatmates 37', '1st Floor, 37 Foley Street, W1W 7TN, London', 'W1W 7TN', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/soft-serve/', '2026-11-14T10:21:30.653Z', 0.85, 'soft serve|flatmates 37|2026-09-25'),
('67d540dc-be4d-407a-ae40-cba1422a4411', 'Autumn Knight: I Can’t Complain', 'exhibition'::event_type, 'a new installation and performance work about the act of complaining, in the first major UK presentation of Knight’s interdisciplinary practice, which draws on theatre, psychology, improvisation, and social exchange', array['Autumn Knight']::text[], array['performance','installation']::text[], array['late','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/11/Thumbnail-AK_optimized_2000.png', '2026-09-29', '2026-11-29', null, null, 'Institute of Contemporary Arts (ICA)', 'The Mall, SW1Y 5AH, London', 'SW1Y 5AH', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/autumn-knight-i-cant-complain/', '2026-11-14T10:21:30.653Z', 0.85, 'autumn knight i can t complain|institute of contemporary arts ica|2026-09-29'),
('c2757e79-b4d0-4987-a108-8e7a73e34024', 'Bridget Riley', 'exhibition'::event_type, 'an exhibition of works spanning over fifty years and three distinct phases of Riley’s career, revealing the remarkable evolution of her exploration of visual perception', '{}'::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Hazlitt-Holland-Hibbert-Bridget-Riley-4.webp', '2026-10-01', '2026-11-27', null, null, 'Hazlitt Holland-Hibbert', '38 Bury Street, St James’s, SW1Y 6BB, London', 'SW1Y 6BB', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/bridget-riley-9/', '2026-11-14T10:21:30.653Z', 0.85, 'bridget riley|hazlitt holland hibbert|2026-10-01'),
('a4473674-0bd7-47f6-ac47-e88fb5fcd63b', 'Andreas Gefeller: Surface Tension', 'exhibition'::event_type, 'new and recent works from four significant series by the German photographer, including the premiere of several new pieces - “an exploration of photography and a reflection on our changing relationship with the world around us', array['Andreas Gefeller']::text[], array['photography']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Atlas-Gallery-Andreas-Gefeller-6.webp', '2026-10-02', '2026-11-14', null, null, 'ATLAS Gallery', '49 Dorset Street, W1U 7NF, London', 'W1U 7NF', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/andreas-gefeller/', '2026-11-14T10:21:30.653Z', 0.85, 'andreas gefeller surface tension|atlas gallery|2026-10-02'),
('5b371d5a-a5be-45b4-a477-25af35ebb18f', 'Sam Doyle: What I Paint is History', 'exhibition'::event_type, 'the first solo UK exhibition dedicated to the life and work of the self-taught painter - a central figure in 20th century African-American art - whose bold works on corrugated roofing, sheet metal, and found lumber filled the front yard of his homestead', array['Sam Doyle']::text[], array['painting']::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/SAM-DOYLE-The-Gallery-of-Everything.jpg', '2026-10-04', '2026-11-22', null, null, 'The Gallery of Everything', '4 Chiltern St, W1U 7PS, London', 'W1U 7PS', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/sam-doyle-what-i-paint-is-history/', '2026-11-14T10:21:30.653Z', 0.85, 'sam doyle what i paint is history|the gallery of everything|2026-10-04'),
('713391ad-b264-47db-a4d3-0e40d32fff7c', 'Iván Argote: Mamarrachos: Quinceañera', 'exhibition'::event_type, 'Argote’s first exhibition at Perrotin London celebrates fifteen years of his eponymous paintings and sculptures originating from digital scribbles - exploring constraint and freedom while inviting the public to participate within the gallery space', array['Iván Argote']::text[], array['painting','sculpture','digital']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Perrotin-London-Ivan-Argote-1.webp', '2026-10-06', '2026-12-19', null, null, 'Perrotin London', 'Claridge’s, Brook’s Mews, W1K 4HR, London', 'W1K 4HR', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/ivan-argote-mamarrachos/', '2026-11-14T10:21:30.653Z', 0.85, 'ivan argote mamarrachos quinceanera|perrotin london|2026-10-06'),
('fc28026e-494d-46d8-a2fe-6d93163a8677', 'PARIS | CUBA - the post-war affair', 'exhibition'::event_type, 'an exhibition exploring the cultural exchange between Cuban communism and the French avant-garde in the 50s and 60s', '{}'::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Opus-Che-Oct-1967-HFA-www.jpg', '2026-10-07', '2026-12-19', null, null, 'Hanina Fine Arts', '21 Woodstock Street, W1C 2AP, London', 'W1C 2AP', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/paris-cuba/', '2026-11-14T10:21:30.653Z', 0.85, 'paris cuba the post war affair|hanina fine arts|2026-10-07'),
('f05b28da-9fb6-44c0-aa2f-ec87e6a1bfe9', 'Charan Singh: Your Tongue in My Mouth', 'exhibition'::event_type, 'curated by Bindi Vora, an exhibition celebrating the lives and resistance of gender fluid communities in India, examining how British colonial rule’s rigid controls on gender expression criminalised established third gender, queer, and trans communities', array['Charan Singh']::text[], '{}'::text[], array['late','political','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/galleriesnow-charan-thumbnail.jpg', '2026-10-08', '2027-02-13', null, null, 'Autograph', 'Rivington Place, EC2A 3BA, London', 'EC2A 3BA', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/charan-singh-your-tongue-in-my-mouth/', '2026-11-14T10:21:30.653Z', 0.85, 'charan singh your tongue in my mouth|autograph|2026-10-08'),
('74dd2f7f-c2d1-421d-aa39-d3740b751194', 'Gülsün Karamustafa: Remains of a Forgotten Promise', 'exhibition'::event_type, 'the first and most comprehensive solo exhibition in the UK of Karamustafa’s practice spans four decades of work across painting, textile, video, installation, and mixed media', array['Gülsün Karamustafa']::text[], array['painting','textiles','film','installation']::text[], array['independent']::text[], null, '2026-10-08', '2026-12-12', null, null, 'Ab-Anbar', '34 Mortimer St, W1W 7JS, London', 'W1W 7JS', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/gulsun-karamustafa/', '2026-11-14T10:21:30.653Z', 0.85, 'gulsun karamustafa remains of a forgotten promise|ab anbar|2026-10-08'),
