('cb3d9fc7-6641-4b25-a898-3e1c4c5e9fb0', 'Justin Caguiat: Change Ringing', 'exhibition'::event_type, 'the painting, sculpture, printmaking, sound, and film in Caguiat’s first UK institutional exhibition explores the architecture, spiritual resonance, and symbolic qualities of sacred spaces, and the structures and rhythms of everyday urban infrastructure', array['Justin Caguiat']::text[], array['printmaking','painting','sculpture','film','sound']::text[], array['blockbuster']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Serpentine-South-Gallery-Justin-Caguiat-1.webp', '2026-10-08', '2027-01-10', null, null, 'Serpentine South Gallery', 'Kensington Gardens, W2 3XA, London', 'W2 3XA', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/justin-caguiat-change-ringing/', '2026-11-14T10:21:30.653Z', 0.85, 'justin caguiat change ringing|serpentine south gallery|2026-10-08'),
('879837cb-6392-4221-a817-dd10383ca0c4', 'Our Bodies Have Been Bridges', 'exhibition'::event_type, 'curated by Mark Sealy and Bindi Vora, a major new exhibition bringing together three feminist artists from across the Americas who use their body to bridge personal and collective memory, indigenous knowledge and relationships to land', '{}'::text[], '{}'::text[], array['late','community','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/09/galleriesnow-thumbnail-our-bodies.jpg', '2026-10-08', '2027-02-13', null, null, 'Autograph', 'Rivington Place, EC2A 3BA, London', 'EC2A 3BA', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/our-bodies-have-been-bridges/', '2026-11-14T10:21:30.653Z', 0.85, 'our bodies have been bridges|autograph|2026-10-08'),
('b4ee92b6-2eca-4c80-af60-047f2a516ac3', 'Reko Rennie: Renaissance Revolution', 'exhibition'::event_type, 'the Aboriginal artist’s first London exhibition begins with a childhood memory of visits to Melbourne’s National Gallery of Victoria and questions who is represented in museums, who decides, and who is left out', array['Reko Rennie']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/26-9_Yavuz-Rennie_3b.jpg', '2026-10-08', '2026-11-14', null, null, 'Ames Yavuz', '31 Grosvenor Hill, W1K 3QU, London', 'W1K 3QU', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/reko-rennie-renaissance-revolution/', '2026-11-14T10:21:30.653Z', 0.85, 'reko rennie renaissance revolution|ames yavuz|2026-10-08'),
('dcc65166-b722-4944-adf3-8f239485ac8d', 'Romuald Hazoumè: My Blue Period', 'exhibition'::event_type, 'addressing historical and modern slavery, migration, and the brutal realities of postcolonial Africa, the internationally renowned artist’s iconic masks made of repurposed plastic containers reflect on the precarious nature of the world we inhabit', array['Romuald Hazoumè']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/October-Gallery-Romuald-Hazoume-1.webp', '2026-10-08', '2026-11-21', null, null, 'October Gallery', '24 Old Gloucester Street, Bloomsbury, WC1N 3AL, London', 'WC1N 3AL', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/romuald-hazoume-my-blue-period/', '2026-11-14T10:21:30.653Z', 0.85, 'romuald hazoume my blue period|october gallery|2026-10-08'),
('47f5e006-e360-4520-af75-18852264037b', 'Tim Garwood: Signals', 'exhibition'::event_type, 'bringing together paintings on birch panel, painted photographs and installation in the form of steel agricultural gates, the exhibition explores what it means to look closely, to slow down and to become attentive to one’s surroundings', array['Tim Garwood']::text[], array['photography','painting','installation']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Sim-Smith-Tim-Garwood-1.webp', '2026-10-08', '2026-11-21', null, null, 'Sim Smith', '6 Camberwell Passage, SE5 0AX, London', 'SE5 0AX', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/tim-garwood-2/', '2026-11-14T10:21:30.653Z', 0.85, 'tim garwood signals|sim smith|2026-10-08'),
('a2fd8dbc-669c-4eb2-ae7c-b40130e6a285', 'Artist Focus. Issy Wood: Self-Portraits', 'exhibition'::event_type, 'this first of three annual focused presentations showcases intimate self-portraits by the British American artist, musician, and writer, who examines intimacy, desire, consumer culture, and the complexities of contemporary identity', array['Artist Focus. Issy Wood']::text[], '{}'::text[], array['late','blockbuster']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2024/01/National-Portrait-Gallery-Forecourt_002_Olivier-Hess.jpg', '2026-10-09', '2027-02-28', null, null, 'National Portrait Gallery', 'St Martin''s Place, WC2H 0HE, London', 'WC2H 0HE', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/artist-focus-issy-wood-self-portraits/', '2026-11-14T10:21:30.653Z', 0.85, 'artist focus issy wood self portraits|national portrait gallery|2026-10-09'),
