('ddf509f9-106b-49bb-a729-25dedec3962a', 'Graham Little', 'exhibition'::event_type, 'new works by Little, “intricate paintings from carefully staged arrangements assembled in his studio using cut paper, found objects gathered from the streets around his home, friends posing as models', '{}'::text[], array['painting']::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Alison-Jacques-Graham-Little-5.webp', '2026-10-09', '2026-11-14', null, null, 'Alison Jacques', '22 Cork Street, W1S 3NG, London', 'W1S 3NG', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/graham-little-5/', '2026-11-14T10:21:30.653Z', 0.85, 'graham little|alison jacques|2026-10-09'),
