('193e9d1b-8f93-4ae5-aada-88fae301b0ba', 'Allen Jones: In Town Tonight', 'exhibition'::event_type, 'the gallery’s first solo exhibition with one of the defining figures of British Pop Art presents a substantial body of new work alongside significant pieces from across his career', array['Allen Jones']::text[], '{}'::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Gazelli-Art-House-London-Allen-Jones-2.webp', '2026-10-12', '2026-12-18', null, null, 'Gazelli Art House', '39 Dover Street, W1S 4NN, London', 'W1S 4NN', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/allen-jones-in-town-tonight/', '2026-11-14T10:21:30.653Z', 0.85, 'allen jones in town tonight|gazelli art house|2026-10-12'),
