('f65bbd46-f907-43d4-a34b-6cdd230628b5', 'Mira Schendel: In Transit', 'exhibition'::event_type, 'organised in collaboration with the artist’s estate and Gomide&Co, São Paulo - and exhibited in both the gallery space and Frieze Masters - an exhibition dedicated to Schendel’s unique material language', array['Mira Schendel']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Luxembourg-Co-Mira-Schendel-1.webp', '2026-10-12', '2026-12-12', null, null, 'Luxembourg + Co.', '2 Savile Row, W1S 3PA, London', 'W1S 3PA', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/mira-schendel-journey-to-the-end-of-language/', '2026-11-14T10:21:30.653Z', 0.85, 'mira schendel in transit|luxembourg co|2026-10-12'),
