('151effae-362a-4fb0-a13f-4fa93a23f62b', 'Glenn Ligon: Prompts', 'exhibition'::event_type, 'the gallery presents a group assembled by Ligon of earlier and new works “which conspicuously inform, contextualise, re-contextualise, appropriate and, somehow, ‘prompt’ one another', array['Glenn Ligon']::text[], '{}'::text[], array['independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Thomas-Dane-Gallery-Glenn-Ligon-5.webp', '2026-10-13', '2026-12-19', null, null, 'Thomas Dane Gallery', '11 Duke Street, St James’s, SW1Y 6BN, London', 'SW1Y 6BN', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/glenn-ligon-prompts/', '2026-11-14T10:21:30.653Z', 0.85, 'glenn ligon prompts|thomas dane gallery|2026-10-13'),
