('ea4d2502-0ee9-471c-ab8a-3675cc458f27', 'Rosalind Nashashibi: Gaza Apollo', 'exhibition'::event_type, 'based around the 2013 discovery of the rare bronze sculpture Apollo, new paintings by Nashashibi in the first solo exhibition of her work in London since her 2020 National Gallery exhibition', array['Rosalind Nashashibi']::text[], array['painting','sculpture']::text[], array['emerging','independent']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/10/Installation-view_Rosalind-Nashashibi_Gaza-Apollo_GRIMM-London-2026_3.jpg', '2026-10-13', '2026-11-21', null, null, 'GRIMM', '43a Duke Street, St James’s, SW1Y 6DD, London', 'SW1Y 6DD', 'West End', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/rosalind-nashashibi-2/', '2026-11-14T10:21:30.653Z', 0.85, 'rosalind nashashibi gaza apollo|grimm|2026-10-13'),
