('abe60233-b0b4-49a5-a580-7b96771d3216', 'Character Changed: The Bloomsbury Group, 1910–1920', 'exhibition'::event_type, 'Drawn predominantly from private collections, the exhibition will include works that have not been exhibited in the last generation, alongside paintings with distinguished exhibition histories.', '{}'::text[], array['painting']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2026-12-09', null, null, 'Philip Mould Gallery', null, null, 'St James', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/character-changed-the-bloomsbury-group-1910-1920-435829/', '2026-11-14T10:21:31.663Z', 0.8, 'character changed the bloomsbury group 1910 1920|philip mould gallery|2026-11-18'),
('1f1116f9-90f2-46cb-ae1a-f4aced276456', 'David Černý: The Glorious 90s in Prague', 'exhibition'::event_type, 'This exhibition explores the story of Prague’s Pink Tank of 1991 alongside some of the artist’s best-known sculptures from the 1990s.', '{}'::text[], array['sculpture']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2026-12-31', null, null, 'Czech Centre London', null, null, 'Kensington', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/david-cerny-the-glorious-90s-in-prague-434231/', '2026-11-14T10:21:31.663Z', 0.8, 'david cerny the glorious 90s in prague|czech centre london|2026-11-18'),
('3165090e-9cd7-4658-a606-85b7852588c3', 'From Concept to Icon: A celebration of UCL’s Wilkins Building by the Survey of London', 'exhibition'::event_type, 'Discover the story of University College London’s iconic Wilkins Building in this architecture exhibition at the UCL Art Museum’s Prints & Drawings Room in Bloomsbury, London.', '{}'::text[], array['printmaking','drawing']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2027-07-28', null, null, 'UCL Art Museum', null, null, 'Euston', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/from-concept-to-icon-a-celebration-of-ucls-wilkins-building-by-the-survey-of-london-431753/', '2026-11-14T10:21:31.663Z', 0.8, 'from concept to icon a celebration of ucl s wilkins building by the survey of london|ucl art museum|2026-11-18'),
('8a8441d2-2122-40dc-a1bf-c3e5c63d9ce7', 'Herbarium | Plants in a New Light', 'exhibition'::event_type, 'An exhibition showcasing the photographs of Swedish artist Lena Granefelt, featured next to the original herbarium specimens from Carl Linnaeus'' pressed plants collection.', '{}'::text[], array['photography']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2027-03-10', null, null, 'The Linnean Society of London', null, null, 'Picadilly', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/herbarium-plants-in-a-new-light-2-435578/', '2026-11-14T10:21:31.663Z', 0.8, 'herbarium plants in a new light|the linnean society of london|2026-11-18'),
('24910c94-0c23-429e-a4b7-7ce338bf6cb7', 'K2 Artistic Expeditions: James Hart Dyke', 'exhibition'::event_type, 'An exhibition of recent paintings and drawings from British artist James Hart Dyke’s gruelling 2025 journey through Pakistan’s Karakoram mountains to paint the daunting K2.', '{}'::text[], array['painting','drawing']::text[], array['independent']::text[], 'https://8400e186.delivery.rocketcdn.me/calendar/wp-content/uploads/sites/5/2026/10/Screenshot-2026-10-05-at-08-42-32-4.2.jpeg.png', '2026-11-18', '2026-11-22', null, null, null, null, null, null, null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/k2-artistic-expeditions-james-hart-dyke-435420/', '2026-11-14T10:21:31.663Z', 0.8, 'k2 artistic expeditions james hart dyke||2026-11-18'),
('6ccef361-14e5-4227-a842-1292acddf3f0', 'Leaders of the Pack: The Women of The Royal Kennel Club Art Collection', 'exhibition'::event_type, 'This exhibition tells the story of how, across three centuries, women found an unlikely route to professional independence: painting dogs.', '{}'::text[], array['painting']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2027-03-26', null, null, 'The Royal Kennel Club art gallery', null, null, 'Picadilly', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/leaders-of-the-pack-the-women-of-the-royal-kennel-club-art-collection-431466/', '2026-11-14T10:21:31.663Z', 0.8, 'leaders of the pack the women of the royal kennel club art collection|the royal kennel club art gallery|2026-11-18'),
('caca2ed9-4b3c-49bf-ab8e-84aec7b24370', 'Londoners on Trial: Crime, Courts and the Public 1244-1924', 'exhibition'::event_type, 'This free exhibition explores the history of law and order in London, uncovering the stories of London’s criminals, victims and law enforcers from the medieval period to modern times.', '{}'::text[], '{}'::text[], array['free','independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2027-02-25', null, null, null, null, null, null, null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/londoners-on-trial-crime-courts-and-the-public-1244-1924-428645/', '2026-11-14T10:21:31.663Z', 0.8, 'londoners on trial crime courts and the public 1244 1924||2026-11-18'),
('6d82e9a7-6d16-4011-a729-6cda9f79a132', 'R. B. Kitaj: From Fragments 1958–1975', 'exhibition'::event_type, 'With paintings, drawings and collages, this exhibition explores the unexpected ways that Kitaj combined source imagery in the early years of his career.', '{}'::text[], array['painting','drawing']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-18', '2026-11-27', null, null, 'Piano Nobile', null, null, 'Notting Hill', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/r-b-kitaj-from-fragments-1958-1975-435051/', '2026-11-14T10:21:31.663Z', 0.8, 'r b kitaj from fragments 1958 1975|piano nobile|2026-11-18'),
('8619c368-0f2b-4532-ae0b-337db8183477', 'The Abbey Art Centre as Postwar Refuge, 1946–56', 'exhibition'::event_type, 'The exhibition unfolds the remarkable story of the Abbey Art Centre, a cosmopolitan art colony established at New Barnet in 1946 by charismatic artist, gallerist and world art collector, William Ohly.', '{}'::text[], '{}'::text[], array['independent']::text[], null, '2026-11-18', '2026-12-18', null, null, 'Ben Uri Gallery', null, null, 'St John''s Wood', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/the-abbey-art-centre-as-postwar-refuge-1946-56-434899/', '2026-11-14T10:21:31.663Z', 0.8, 'the abbey art centre as postwar refuge 1946 56|ben uri gallery|2026-11-18'),
