('61fb9d0c-05c8-49c6-a2b7-28e7fe44442f', 'Peggy Guggenheim in London', 'exhibition'::event_type, 'In the late 1930s, Peggy Guggenheim launched an art gallery in Mayfair that shocked the conservative tastes of the British art establishment. This exhibition revisits the gallery that helped redefine London’s contemporary art scene.', '{}'::text[], '{}'::text[], array['late','blockbuster']::text[], null, '2026-11-22', '2027-03-14', null, null, 'Royal Academy of Arts', null, null, 'Picadilly', null, null, 'paid'::price_type, 19.5, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/peggy-guggenheim-in-london-434831/', '2026-11-14T10:21:32.549Z', 0.8, 'peggy guggenheim in london|royal academy of arts|2026-11-22'),
('89e6d93e-e5a0-45d0-a40a-e66f3ef5047b', 'Tove Jansson and her Families', 'exhibition'::event_type, 'Uncovering the personal relationships behind the celebrated artist, this exhibition will look at the people who shaped Finnish author-illustrator Tove Jansson’s life and work – the UK’s first ever exhibition to focus on Tove Jansson’s work as an illustrator.', '{}'::text[], array['illustration']::text[], array['family','independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-22', '2027-05-09', null, null, 'Quentin Blake Centre for Illustration', null, null, 'Clerkenwell', null, null, 'paid'::price_type, 15, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/tove-jansson-and-her-families-434846/', '2026-11-14T10:21:32.549Z', 0.8, 'tove jansson and her families|quentin blake centre for illustration|2026-11-22'),
('e3d14111-3101-42bf-a03c-c680fcd50e78', 'Andrius Arutiunian: They Tried to Count Us', 'exhibition'::event_type, 'Humanity’s continuous quest to define the afterlife and existence beyond our planet lies at the heart of the Armenian-Lithuanian artist’s first UK solo show.', array['Andrius Arutiunian']::text[], '{}'::text[], array['late','blockbuster']::text[], 'https://www.galleriesnow.net/wp-content/uploads/2026/11/Hayward-Gallery_Andrius-Arutiunian.webp', '2026-11-24', '2027-03-07', null, null, 'Hayward Gallery', 'Belvedere Road, SE1 8XX, London', 'SE1 8XX', 'London', null, null, 'free'::price_type, 0, null, null, 'GalleriesNow', 'https://www.galleriesnow.net/shows/andrius-arutiunian-they-tried-to-count-us/', '2026-11-14T10:21:30.653Z', 0.85, 'andrius arutiunian they tried to count us|hayward gallery|2026-11-24'),
