('22cbdaa3-f8a4-4f89-ad7b-d2e4680feeec', 'Peter Blake: In the Studio', 'exhibition'::event_type, 'An exhibition showcasing the life and work of one of the most celebrated and influential artists of 20th century Britain — Sir Peter Blake.', '{}'::text[], '{}'::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-26', '2027-04-04', null, null, 'Pitzhanger Manor & Gallery', null, null, 'Ealing', null, null, 'paid'::price_type, 14, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/peter-blake-in-the-studio-429776/', '2026-11-14T10:21:33.420Z', 0.8, 'peter blake in the studio|pitzhanger manor gallery|2026-11-26'),
