('be157cc8-6f1b-4b56-a542-36116c1620dd', 'Royal Institute of Oil Painters | Annual Exhibition 2026', 'exhibition'::event_type, 'This year’s optional theme, ‘Winter Rituals’, invites artists to explore the season’s rhythms and traditions in their own unique way.', '{}'::text[], array['painting']::text[], array['independent']::text[], null, '2026-11-26', '2026-12-12', null, null, 'Mall Galleries', null, null, 'St James', null, null, 'paid'::price_type, 7, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/royal-institute-of-oil-painters-annual-exhibition-2026-436569/', '2026-11-14T10:21:33.420Z', 0.8, 'royal institute of oil painters annual exhibition 2026|mall galleries|2026-11-26'),
('005e5153-02c2-40c1-aa71-206ae429c190', 'The 544: A photographic memorial', 'exhibition'::event_type, 'This exhibition features 544 individual cyanotype photographic images to symbolise and bring individuality to 544 anonymous people who have become forever grouped together as victims of a horrific mass murder at the Daugavpils psychiatric hospital in Latvia in 1941.', '{}'::text[], array['photography']::text[], array['independent']::text[], 'data:image/svg+xml,%3Csvg%20xmlns=''http://www.w3.org/2000/svg''%20viewBox=''0%200%20150%20150''%3E%3C/svg%3E', '2026-11-26', '2027-03-06', null, null, 'Bethlem Museum of the Mind', null, null, 'Beckenham', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/the-544-a-photographic-memorial-436293/', '2026-11-14T10:21:33.420Z', 0.8, 'the 544 a photographic memorial|bethlem museum of the mind|2026-11-26'),
('2d0591da-3fe9-4b84-a146-cf3b4e1a28af', 'WOMEN AT WORK, Sarah Ainslie’s East End Portraits 1992-2025', 'exhibition'::event_type, 'Sarah Ainslie’s long-term project celebrates the contribution of female labour in exuberant photographs that capture the passion and struggle of the working life', '{}'::text[], array['photography']::text[], array['independent']::text[], null, '2026-11-26', '2026-12-12', null, null, 'Four Corners Gallery', null, null, 'Bethnal Green', null, null, 'free'::price_type, 0, null, null, 'IanVisits', 'https://www.ianvisits.co.uk/calendar/women-at-work-sarah-ainslies-east-end-portraits-1992-2025-436518/', '2026-11-14T10:21:33.420Z', 0.8, 'women at work sarah ainslie s east end portraits 1992 2025|four corners gallery|2026-11-26'),
